// --- A.1 FFT ---------------------------------------------------------------
//
// 512 samples lroundf(8000 * sinf(2 pi f i / 16000)), then computeDominantFrequency() at 16 kHz;
// expected within 0.01 Hz (cosf differs between libm).

struct FftVector {
    float inputHz;
    float expectedHz;
};

// clang-format off: one row per line of Annex A.
constexpr FftVector FFT_VECTORS[] = {
    {440.00f, 440.2000f},
    {523.25f, 522.7604f},
    {1000.00f, 1000.0001f},
    {2000.00f, 2000.0000f},
    {2730.00f, 2730.4541f},
    {4100.00f, 4100.4336f},
};
// clang-format on

constexpr size_t FFT_VECTOR_COUNT = sizeof(FFT_VECTORS) / sizeof(FFT_VECTORS[0]);
static_assert(FFT_VECTOR_COUNT == 6, "Annex A.1 has 6 FFT pairs");

// --- A.2 Level (whole processBlock() chain) --------------------------------
//
// LEVEL_BYTES_PER_SLOT bytes per input (420 ms): the 1 kHz sigma-delta sines of amplitude 0.25 and
// 0.1 (no offset) and the LCG seeded with 11. SAI frames: microphone on slot 0, slot 1 at 0x00
// (frame[2i] = mic[i], frame[2i + 1] = 0). Each line: a new SteamiIMP34DT05, setVolume(volume),
// setLevelWindowMs(windowMs), then one 320-byte block per processBlock() call; after each block,
// level() when levelReady(). The line stops after `windows` windows (20 for 1 ms, 10 for 10 ms,
// 3 for 100 ms). lvFnv is the FNV-1a, over those windows in order, of the 4 bytes (little endian)
// of the bits of rms then the 2 bytes of peak. rms0 to spl0 describe the first window: blocks,
// windows, lvFnv, rms0Bits and peak0 are exact, dbfs0 and spl0 within 0.01 dB.

enum class LevelInput : uint8_t { SINE_1K_A025, SINE_1K_A010, RANDOM_11 };

constexpr size_t LEVEL_BYTES_PER_SLOT = 67200;

// FNV-1a of the LEVEL_BYTES_PER_SLOT microphone bytes of each LevelInput.
constexpr uint32_t LEVEL_INPUT_FNV[] = {0xa73703e3U, 0xa55e5e3fU, 0xf64932cbU};

struct LevelVector {
    LevelInput input;
    uint8_t volume;
    uint16_t windowMs;
    uint8_t slot;
    uint16_t blocks;  // blocks sent
    uint8_t windows;  // windows read
    uint32_t lvFnv;
    uint32_t rms0Bits;
    float rms0;
    uint16_t peak0;
    float dbfs0;
    float spl0;
};

